<header class="page-heading"><span class="eyebrow"><?=t('ЖУРНАЛ ФАБРИКИ','FACTORY JOURNAL')?></span><h1><?=h($pageTitle)?></h1></header><div class="journal-grid"><?php foreach($articles as $article):?><article><?php if($article['image']):?><a href="/article/<?=$article['id']?>"><img src="<?=h($article['image'])?>" alt="<?=h(tr($article))?>" width="640" height="400" loading="lazy"></a><?php endif;?><time><?=h($article['publish_date'])?></time><h2><a href="/article/<?=$article['id']?>"><?=h(tr($article))?></a></h2><p><?=h(mb_substr(strip_tags(tr($article,'body')),0,170))?>…</p><a class="text-link" href="/article/<?=$article['id']?>"><?=t('Подробнее','Read more')?> ↗</a></article><?php endforeach;?></div><?php if(!$articles):?><p><?=t('Публикаций пока нет.','No publications yet.')?></p><?php endif;?>
